def _stored_question(result: object) -> str:
    chunk = result.chunk
    metadata = chunk.metadata or {}
    stored = str(metadata.get("question") or "")
    if stored.strip():
        return stored
    for line in chunk.chunk_text.splitlines():
        if line.lower().startswith("question:"):
            return line.split(":", 1)[1]
    return ""

